.form-row { display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap; }

.btn {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0.5rem 0.9rem;
  font-size: 0.9rem;
  cursor: pointer;
  background: #eef1f5;
  color: var(--ink);
}
.btn:hover { filter: brightness(0.97); }
.btn--primary { background: var(--brand); color: var(--brand-ink); }
.btn--ghost { background: transparent; border-color: var(--line); }
.btn--danger { color: var(--danger); border-color: transparent; }
.btn--danger:hover { background: #fbeaea; }

.form-error { color: var(--danger); font-size: 0.88rem; margin: 0; }

.controls {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1rem;
}
.tag-filters { display: flex; flex-wrap: wrap; gap: 0.4rem; }
