  border-radius: 999px;
  padding: 0.25rem 0.7rem;
  font-size: 0.82rem;
  cursor: pointer;
  color: var(--muted);
}
.tag-filter--active { background: var(--brand); color: #fff; border-color: var(--brand); }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.75rem; }

.bookmark {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1rem;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}
.bookmark__main { min-width: 0; flex: 1; }
.bookmark__title {
  display: block;
  font-weight: 600;
  color: var(--ink);
