  overflow: hidden;
  text-overflow: ellipsis;
}
.bookmark__title:hover { color: var(--brand); text-decoration: underline; }
.bookmark__url {
  display: block;
  color: var(--muted);
  font-size: 0.85rem;
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bookmark__meta {
