  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  margin-top: 0.5rem;
  align-items: center;
}
.bookmark__tags { display: flex; flex-wrap: wrap; gap: 0.3rem; }
.tag {
  background: #eef2fb;
  color: var(--brand);
  border-radius: 999px;
  padding: 0.1rem 0.55rem;
  font-size: 0.78rem;
}
.bookmark__date { color: var(--muted); font-size: 0.78rem; }
.bookmark__actions { display: flex; gap: 0.4rem; flex-shrink: 0; }

.bookmark--editing { display: block; }
.edit-form .field { margin-bottom: 0.6rem; }

.state {
  text-align: center;
  color: var(--muted);
  padding: 2.5rem 1rem;
  background: var(--card);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

@media (max-width: 520px) {
  .bookmark { flex-direction: column; }
  .bookmark__actions { align-self: flex-end; }
}

